#include <print>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> a = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
    long long cur = a[0], best = a[0];
    for (int i = 1; i < (int)a.size(); ++i) {
        cur = std::max((long long)a[i], cur + a[i]);
        if (cur > best) best = cur;
        std::println("i={} cur={}", i, cur);
    }
    std::println("最大子数组和 = {}", best);

    std::vector<int> b = {-5, -2, -8};
    long long cur2 = b[0], best2 = b[0];
    for (int i = 1; i < 3; ++i) {
        cur2 = std::max((long long)b[i], cur2 + b[i]);
        if (cur2 > best2) best2 = cur2;
    }
    std::println("全负数组答案 = {}", best2);
    return 0;
}

